CREATE TABLE "pos"."member_card_batches" (
	"id" integer PRIMARY KEY GENERATED BY DEFAULT AS IDENTITY (sequence name "pos"."member_card_batches_id_seq" INCREMENT BY 1 MINVALUE 1 MAXVALUE 2147483647 START WITH 1 CACHE 1),
	"batch_code" text NOT NULL,
	"label" text DEFAULT '' NOT NULL,
	"quantity" integer NOT NULL,
	"branch_id" integer DEFAULT pos.default_branch_id() NOT NULL,
	"created_by_staff_id" integer,
	"created_at" timestamp with time zone DEFAULT now() NOT NULL,
	CONSTRAINT "member_card_batches_batch_code_unique" UNIQUE("batch_code"),
	CONSTRAINT "member_card_batches_quantity_check" CHECK ("pos"."member_card_batches"."quantity" between 1 and 500)
);
