CREATE TABLE "pos"."member_cards" (
	"id" integer PRIMARY KEY GENERATED BY DEFAULT AS IDENTITY (sequence name "pos"."member_cards_id_seq" INCREMENT BY 1 MINVALUE 1 MAXVALUE 2147483647 START WITH 1 CACHE 1),
	"batch_id" integer,
	"member_code" text NOT NULL,
	"status" text DEFAULT 'unused' NOT NULL,
	"activated_member_id" integer,
	"activated_at" timestamp with time zone,
	"created_at" timestamp with time zone DEFAULT now() NOT NULL,
	CONSTRAINT "member_cards_member_code_unique" UNIQUE("member_code"),
	CONSTRAINT "member_cards_activated_member_id_unique" UNIQUE("activated_member_id"),
	CONSTRAINT "member_cards_status_check" CHECK ("pos"."member_cards"."status" in ('unused', 'activated', 'void')),
	CONSTRAINT "member_cards_activation_check" CHECK (("pos"."member_cards"."status" = 'unused' and "pos"."member_cards"."activated_member_id" is null and "pos"."member_cards"."activated_at" is null)
          or ("pos"."member_cards"."status" = 'activated' and "pos"."member_cards"."activated_at" is not null)
          or ("pos"."member_cards"."status" = 'void' and "pos"."member_cards"."activated_member_id" is null))
);
