-- ลงทะเบียนเลขบัตร 16 หลักที่เปิดใช้งานอยู่ก่อนเพิ่มระบบสต๊อกบัตร
INSERT INTO "pos"."member_cards" (
  "member_code",
  "status",
  "activated_member_id",
  "activated_at",
  "created_at"
)
SELECT
  "member_code",
  'activated',
  "id",
  "card_activated_at",
  "created_at"
FROM "pos"."members"
WHERE "member_code" ~ '^88[0-9]{14}$'
ON CONFLICT ("member_code") DO NOTHING;--> statement-breakpoint

